class _EcgPainter extends CustomPainter{final String p;_EcgPainter(this.p);@override void paint(Canvas canvas,Size s){canvas.drawRect(Offset.zero&s,Paint()..color=const Color(0xFFFFFBFB));final minor=Paint()..color=const Color(0xFFF3DCDD)..strokeWidth=.6;final major=Paint()..color=const Color(0xFFE9BFC3)..strokeWidth=1;for(double x=0;x<s.width;x+=5){canvas.drawLine(Offset(x,0),Offset(x,s.height),x%25==0?major:minor);}for(double y=0;y<s.height;y+=5){canvas.drawLine(Offset(0,y),Offset(s.width,y),y%25==0?major:minor);}final base=s.height*.56;final path=Path()..moveTo(0,base);final dx=s.width/900;for(int i=0;i<=900;i++){final phase=i%100;double v=0;if(p=='vf'||p=='torsades'){v=(p=='vf'?10:16)*((i*37%19)-9)/9.0+(p=='torsades'?10*Math.sin(i/18):0);}else if(p=='asystole'){v=0;}else{final wide=['vt','wpw','lbbb','rbbb','ivcd','paced'].contains(p);if(phase>=10&&phase<17)v=-5;if(phase>=17&&phase<22)v=wide?45:31;if(phase>=22&&phase<27)v=-12;if(phase>=37&&phase<52)v=-8*Math.sin((phase-37)/15*3.14159);if(phase>=68&&phase<92)v=(p=='hyperk'?-19:-10)*Math.sin((phase-68)/24*3.14159);if(['stemi','rvmi','posterior','peri','ischemia','wellens','dewinter'].contains(p)&&phase>=28&&phase<68)v+=p=='ischemia'?-5:5;if(p=='hyperk'&&phase>=68&&phase<92)v=-22*Math.sin((phase-68)/24*3.14159);if(p=='hypok'&&phase>=52&&phase<68)v=0;if(p=='longqt'&&phase>=52&&phase<98)v=-8*Math.sin((phase-52)/46*3.14159);if(['af','flutter','mat'].contains(p)&&phase<10)v+=((i*13%7)-3)*1.4;if(p=='complete'&&phase>=10&&phase<27)v=0;}path.lineTo(i*dx,base-v);}canvas.drawPath(path,Paint()..color=const Color(0xFFB33445)..style=PaintingStyle.stroke..strokeWidth=2..strokeCap=StrokeCap.round);}@override bool shouldRepaint(covariant _EcgPainter old)=>old.p!=p;}
